import('./src/dates.js').then(dates => {
  // Simulate original nextCharge function
  const MONTHS_PER_CHARGE = { 'monthly': 1, 'yearly': 12 };

  function nextCharge(sub, today) {
    const step = MONTHS_PER_CHARGE[sub.cycle];
    let n = 0;
    let date = sub.since;
    while (date < today) {
      n += 1;
      date = dates.addMonths(sub.since, n * step);
    }
    return date;
  }

  // Test
  const gym = { cycle: 'monthly', since: '2026-09-02' };
  const music = { cycle: 'monthly', since: '2026-09-30' };
  const today = '2026-10-25';

  const gymDate = nextCharge(gym, today);
  const musicDate = nextCharge(music, today);

  console.log('Gym:', gymDate);
  console.log('Music:', musicDate);
  console.log('Sorted by shortLabel:');
  const labels = [
    { name: 'Gym', date: gymDate, when: gymDate.slice(5).split('-')[1] + ' ' + ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][parseInt(gymDate.slice(5, 7)) - 1] },
    { name: 'Music', date: musicDate, when: musicDate.slice(5).split('-')[1] + ' ' + ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][parseInt(musicDate.slice(5, 7)) - 1] }
  ];
  console.log(labels.map(l => l.when));
  const sorted = labels.sort((a, b) => a.when.localeCompare(b.when));
  console.log('After sort:', sorted.map(s => s.date));
});
" 2>&1

